#!/bin/sh
# Builds the Prosody player's synth for the browser (docs/player.md §5):
#
#   synth.js         its bindings, generated by `wasm-bindgen`, which the render worker loads
#   synth_bg.wasm    the synth (`crates/prosody-synth-wasm`)
#
# into web/public by default, so that both the page Vite builds (web/dist, which `prosody-web`
# serves) and the page `npm --prefix web run dev` serves carry it; git ignores the two files there.
# Without them the player cannot start, and says so. `scripts/build-site.sh` runs this too.
#
#   ./scripts/build-synth.sh          into web/public
#   ./scripts/build-synth.sh DIR      into DIR
set -eu

here=$(dirname "$0")
cd "$here/.."
dir="${1:-web/public}"

# The synth has no C in it (unlike the compiler's parser), so the host's own archiver will do.
cargo build --release --locked -p prosody-synth-wasm --target wasm32-unknown-unknown
bindgen=$(./scripts/wasm-bindgen.sh)
target_dir=$(cargo metadata --format-version 1 --no-deps |
  grep -o '"target_directory":"[^"]*"' | cut -d'"' -f4)
mkdir -p "$dir"
"$bindgen" --target web --no-typescript --out-name synth --out-dir "$dir" \
  "$target_dir/wasm32-unknown-unknown/release/prosody_synth_wasm.wasm"
echo "build-synth: $(wc -c < "$dir/synth_bg.wasm" | tr -d ' ') bytes of synth_bg.wasm in $dir"
